// Prepare content for extraction
const input = $input.first().json;
const content = input.body?.content || input.content || '';
const schema = input.body?.schema || input.schema || null;

if (!content) {
  throw new Error('No content provided for extraction');
}

// Default schema if none provided
const defaultSchema = {
  type: 'object',
  properties: {
    entities: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          type: { type: 'string' },
          value: { type: 'string' }
        }
      }
    },
    dates: { type: 'array', items: { type: 'string' } },
    amounts: { type: 'array', items: { type: 'number' } },
    summary: { type: 'string' }
  }
};

return [{
  json: {
    content,
    schema: schema || defaultSchema,
    schemaString: JSON.stringify(schema || defaultSchema, null, 2)
  }
}];

