// Parse and validate extracted data
const input = $input.first().json;
let extracted;

try {
  const content = input.message?.content || input.choices?.[0]?.message?.content || '{}';
  extracted = JSON.parse(content);
} catch (e) {
  return [{
    json: {
      success: false,
      error: 'Failed to parse AI response as JSON',
      rawResponse: input.message?.content || input.choices?.[0]?.message?.content
    }
  }];
}

return [{
  json: {
    success: true,
    extracted,
    metadata: {
      extractedAt: new Date().toISOString(),
      model: 'gpt-4o-mini',
      contentLength: $('Prepare Extraction').first().json.content.length
    }
  }
}];
